css:
/* Remove the standard ERPNext website chrome on this custom dashboard page. */
/* Compact Today's queue table */
.life-dashboard-kpis{display:grid;grid-template-columns:repeat(6,minmax(120px,1fr));gap:11px;margin:12px 0 14px}.life-dashboard-kpi{position:relative;background:#fff;border:1px solid #d5ddd2;border-radius:4px;padding:13px 15px;box-shadow:0 1px 2px rgba(20,45,25,.05);overflow:hidden;text-align:left;cursor:pointer;color:inherit;transition:.16s}.life-dashboard-kpi:hover{transform:translateY(-2px);box-shadow:0 5px 14px rgba(20,45,25,.12);border-color:#9aae9b}.life-dashboard-kpi:focus{outline:2px solid #b8860b;outline-offset:2px}.life-dashboard-kpi:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:#176038}.life-dashboard-kpi.red:before{background:#b32419}.life-dashboard-kpi.leaf:before{background:#86c83e}.life-dashboard-kpi.blue:before{background:#245f96}.life-dashboard-kpi.amber:before{background:#a86e00}.life-dashboard-kpi small{display:block;color:#778379;text-transform:uppercase;letter-spacing:1px;font-size:9.5px}.life-dashboard-kpi b{display:block;font:25px Georgia;color:#195c36;margin:5px 0 2px}.life-dashboard-kpi.red b{color:#ae251b}.life-dashboard-kpi.blue b{color:#245f96}.life-dashboard-kpi.amber b{color:#9b6600}.life-dashboard-kpi span{color:#748076;font-size:9.5px}.life-queue-filters label{font-size:9px;color:#718074;text-transform:uppercase}.life-queue-filters label input{display:block;width:135px;height:42px;border:1px solid var(--line);border-radius:4px;background:#fff;padding:0 9px;color:var(--ink);font-size:11px}.life-queue-filters select{min-width:190px}@media(max-width:1200px){.life-dashboard-kpis{grid-template-columns:repeat(3,1fr)}.life-queue-filters{flex-wrap:wrap}.life-queue-card>header{align-items:flex-end}}@media(max-width:700px){.life-dashboard-kpis{grid-template-columns:repeat(2,1fr)}.life-queue-filters label input,.life-queue-filters select{width:100%;min-width:0}}
#lifeHealthcareApp .life-queue-card .life-table-wrap{margin:12px 14px}#lifeHealthcareApp .life-queue-card .life-table{font-size:11.5px}#lifeHealthcareApp .life-queue-card .life-table th{padding:8px 10px;font-size:9.5px;letter-spacing:.6px}#lifeHealthcareApp .life-queue-card .life-table td{padding:7px 10px;line-height:1.25}#lifeHealthcareApp .life-queue-card .life-client-cell{min-width:235px;gap:8px}#lifeHealthcareApp .life-queue-card .life-client-avatar{width:30px;height:30px;font-size:11px}#lifeHealthcareApp .life-queue-card .life-contact-tag{margin-left:5px;padding:1px 6px;font-size:8.5px}#lifeHealthcareApp .life-queue-card .life-sub,#lifeHealthcareApp .life-queue-card small{font-size:9px;margin-top:2px}#lifeHealthcareApp .life-queue-card .life-badge{font-size:8.5px;padding:1px 5px}#lifeHealthcareApp .life-queue-card .life-queue-actions{gap:3px}#lifeHealthcareApp .life-queue-card .life-queue-actions .life-btn,#lifeHealthcareApp .life-queue-card .life-queue-actions .life-link{padding:4px 7px;font-size:10px;line-height:1.15}#lifeHealthcareApp .life-queue-card .life-branch-link,#lifeHealthcareApp .life-queue-card .life-link{font-size:11px}#lifeHealthcareApp .life-queue-card .life-table th:nth-child(1),#lifeHealthcareApp .life-queue-card .life-table td:nth-child(1){width:105px;min-width:105px;white-space:nowrap}#lifeHealthcareApp .life-queue-card .life-table th:nth-child(3),#lifeHealthcareApp .life-queue-card .life-table td:nth-child(3){min-width:135px;white-space:nowrap}#lifeHealthcareApp .life-queue-card .life-table th:nth-child(6),#lifeHealthcareApp .life-queue-card .life-table td:nth-child(6){min-width:145px;white-space:nowrap}#lifeHealthcareApp .life-queue-card .life-table td:nth-child(1) .life-sub,#lifeHealthcareApp .life-queue-card .life-branch-link{white-space:nowrap}
body>.navbar,body>nav.navbar,.navbar.navbar-light,.web-footer,footer.web-footer,.page-footer,.page-header,.page-breadcrumbs,.breadcrumb-container,.page_content>.page-header,.page_content>.web-footer{display:none!important}
.life-popup.kpi-mode{width:min(1380px,95vw);max-height:88vh;background:#f6f8f4}.life-popup.kpi-mode>header{background:#15552f;border-bottom:2px solid #b8860b}.life-popup.kpi-mode>header h2{color:#fff}.life-popup.kpi-mode #branchPopupBody{padding:16px}.life-kpi-popup-hero{display:flex;gap:12px;background:linear-gradient(100deg,#15552f,#287342);color:#fff;border-bottom:2px solid #c29314;padding:16px 18px;margin:-16px -16px 15px}.life-kpi-popup-hero>div{min-width:220px}.life-kpi-popup-hero small,.life-kpi-popup-hero b{display:block}.life-kpi-popup-hero small{color:#dbeadd;font-size:10px;text-transform:uppercase;letter-spacing:.8px}.life-kpi-popup-hero b{font:27px Georgia;margin-top:5px}.life-kpi-popup-table{background:#fff;border:1px solid #d4ddd2;border-radius:4px}.life-kpi-popup-table .life-table{font-size:11px}.life-kpi-popup-table .life-table th{padding:8px 10px}.life-kpi-popup-table .life-table td{padding:7px 10px}.life-kpi-popup-table .life-btn{font-size:10px;padding:5px 8px}


body,main,.page-container,.page_content,.web-page-content,.page_content>.container,.page-container>.container{margin:0!important;padding:0!important;max-width:none!important;width:100%!important}


.page_content>.container>.row,.web-page-content>.row{margin:0!important}


.page_content>.container>.row>[class*="col-"],.web-page-content>.row>[class*="col-"]{padding:0!important;max-width:100%!important;flex:0 0 100%!important}


html,body{background:#f4f6f1!important;min-height:100%;overflow-x:hidden}


#lifeHealthcareApp{--forest:#143a21;--green:#1e5631;--leaf:#8cc63f;--gold:#b8860b;--paper:#f4f6f1;--card:#fff;--line:#d7ded4;--ink:#1a2620;--muted:#71806f;--red:#a32217;--amber:#9a6400;--blue:#1c4e80;font-family:"Segoe UI",Arial,sans-serif;color:var(--ink);background:var(--paper);min-height:100vh;width:100%;display:flex;font-size:13px;line-height:1.35}


#lifeHealthcareApp *{box-sizing:border-box}

#lifeHealthcareApp button,#lifeHealthcareApp input,#lifeHealthcareApp select{font:inherit}

#lifeHealthcareApp button{cursor:pointer}


.life-app[data-active-view="overview"] .life-filter-card,.life-app[data-active-view="overview"] #lifeRefresh,.life-app[data-active-view="overview"] #lifePrint{display:none!important}


.life-app[data-active-view="overview"] #view-overview{padding:0 20px 28px}


.life-app[data-active-view="overview"] .life-alert{margin-top:12px}


.life-side{position:sticky;top:0;height:100vh;width:220px;flex:0 0 220px;background:var(--forest);color:#dce7dd;transition:.18s;z-index:25;border-right:1px solid rgba(184,134,11,.65)}


.life-side.collapsed{width:58px;flex-basis:58px}


.life-side.collapsed .life-brand-text,.life-side.collapsed nav p,.life-side.collapsed nav b,.life-side.collapsed nav i,.life-side.collapsed .life-side-foot{display:none}


.life-side.collapsed nav button{justify-content:center;padding:10px 0}


.life-brand{height:61px;padding:14px;display:flex;align-items:center;gap:10px;border-bottom:1px solid rgba(184,134,11,.55);background:linear-gradient(rgba(184,134,11,.13),transparent)}


.life-mark{width:31px;height:31px;flex:none;border-radius:5px;display:grid;place-items:center;background:var(--leaf);color:var(--forest);font:700 17px Georgia}


.life-brand-text b{display:block;color:white;font:15px Georgia}


.life-brand-text small{display:block;color:var(--leaf);font-size:9px;letter-spacing:1.4px;text-transform:uppercase;margin-top:2px}


.life-side nav{overflow:auto;height:calc(100vh - 102px);padding:7px 0}


.life-side nav p{font-size:9px;letter-spacing:1.3px;text-transform:uppercase;color:#c2a65f;padding:13px 16px 6px;margin:3px 0 0;border-top:1px solid rgba(184,134,11,.35)}


.life-side nav p:first-child{border:0}


.life-side nav button{width:100%;border:0;border-left:3px solid transparent;border-bottom:1px solid rgba(184,134,11,.21);background:none;color:#cfdbd0;display:flex;align-items:center;gap:9px;padding:10px 15px;text-align:left}


.life-side nav button:hover,.life-side nav button.active{background:rgba(140,198,63,.14);color:#fff}


.life-side nav button.active{border-left-color:var(--gold)}


.life-side nav button span{width:18px;text-align:center}


.life-side nav button b{font-weight:500;flex:1}


.life-side nav button i{font-style:normal;font-size:10px;background:var(--leaf);color:var(--forest);padding:1px 6px;border-radius:10px;font-weight:700}


.life-side-foot{height:41px;padding:12px 14px;border-top:1px solid rgba(184,134,11,.55);font-size:10px;color:#91a694}


.life-edge{position:fixed;z-index:27;left:212px;top:50%;width:17px;height:53px;border:1px solid var(--gold);background:white;color:var(--gold);border-radius:9px;transition:.18s}


.life-side.collapsed+.life-edge{left:50px}


.life-main{min-width:0;flex:1}

.life-page-heading{display:flex;align-items:center;gap:12px;min-width:0}

.life-healthcare-button{display:inline-flex;align-items:center;justify-content:center;min-height:31px;padding:6px 11px;border:1px solid #c8d2c7;border-radius:4px;background:#fff;color:#15552f;text-decoration:none;font-size:11px;font-weight:600;white-space:nowrap;box-shadow:0 1px 2px rgba(20,45,25,.05)}

.life-healthcare-button:hover{background:#edf5e9;border-color:#8eaa91;color:#0f4325;text-decoration:none}

.life-healthcare-button:focus{outline:2px solid #b8860b;outline-offset:2px}


.life-topbar{height:61px;position:sticky;top:0;z-index:20;background:#fff;border-bottom:1px solid var(--line);padding:0 22px;display:flex;align-items:center;justify-content:space-between}


.life-topbar h1{margin:0;font:18px Georgia}


.life-topbar small{color:var(--muted)}


.life-top-actions,.life-user{display:flex;align-items:center;gap:10px}


.life-user{border-left:1px solid var(--line);padding-left:13px}


.life-user>span{width:33px;height:33px;border-radius:50%;display:grid;place-items:center;background:var(--green);color:#fff;font-weight:700}


.life-user b,.life-user small{display:block}


.life-user small{font-size:10px;margin-top:2px}


.life-clock{text-align:right;padding-right:12px;border-right:1px solid var(--line)}


.life-clock b,.life-clock small{display:block}


.life-clock b{color:var(--green);font-size:13px}


.life-clock small{font-size:10px;margin-top:2px}


.life-btn{border:1px solid var(--line);border-radius:4px;background:#fff;padding:7px 11px;color:var(--ink)}


.life-btn.primary{background:var(--green);color:#fff;border-color:var(--green)}


.life-btn:hover{filter:brightness(.97)}


.life-filter-card{margin:14px 16px 10px;background:#fff;border:1px solid var(--line);border-top:2px solid var(--gold);border-radius:4px}


.life-filter-title{padding:9px 12px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between}


.life-filter-title b,.life-filter-title small{display:block}


.life-filter-title b{font-size:10px;letter-spacing:1.1px;color:var(--green)}


.life-filter-title small,.life-filter-title>span{font-size:10px;color:var(--muted);margin-top:3px}


.life-filter-grid{display:grid;grid-template-columns:145px 145px minmax(190px,1fr) minmax(220px,1.2fr) auto;gap:10px;padding:10px 12px;align-items:end}


.life-filter-grid label{font-size:10px;color:var(--muted);font-weight:600}


.life-filter-grid input,.life-filter-grid select{display:block;width:100%;height:33px;margin-top:4px;border:1px solid var(--line);border-radius:3px;background:#fff;padding:0 9px;color:var(--ink)}


.life-filter-buttons{display:flex;gap:7px}


.life-view{display:none;padding:2px 16px 28px}


.life-view.active{display:block}


.life-loading{margin:14px 16px;padding:22px;text-align:center;color:var(--muted);background:white;border:1px solid var(--line)}


.life-loading span{display:inline-block;width:15px;height:15px;border:2px solid var(--line);border-top-color:var(--green);border-radius:50%;animation:lifeSpin .7s linear infinite;vertical-align:-3px;margin-right:7px}

@keyframes lifeSpin{to{transform:rotate(360deg)}

}


.life-alert{margin:12px 20px;padding:10px 12px;border:1px solid #ebd3a6;background:#fdf3e0;color:#795400;border-radius:4px}


.life-kpis{display:grid;grid-template-columns:repeat(6,minmax(130px,1fr));gap:11px;margin-bottom:13px}


.life-kpi{position:relative;overflow:hidden;background:#fff;border:1px solid var(--line);border-radius:4px;padding:13px}


.life-kpi:before{content:"";position:absolute;left:0;top:0;bottom:0;width:3px;background:var(--green)}


.life-kpi.amber:before{background:var(--amber)}


.life-kpi.red:before{background:var(--red)}


.life-kpi.blue:before{background:var(--blue)}


.life-kpi small{font-size:9.5px;letter-spacing:.9px;text-transform:uppercase;color:var(--muted)}


.life-kpi strong{display:block;font:25px Georgia;color:var(--green);margin:4px 0 2px}


.life-kpi.red strong{color:var(--red)}


.life-kpi.amber strong{color:var(--amber)}


.life-kpi em{font-style:normal;font-size:10px;color:var(--muted)}


.life-two-col{display:grid;grid-template-columns:1.25fr .75fr;gap:13px;margin-bottom:13px}


.life-card{background:#fff;border:1px solid var(--line);border-radius:4px;margin-bottom:13px;box-shadow:0 1px 2px rgba(20,45,25,.04)}


.life-card>header{min-height:48px;padding:10px 13px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:10px;background:linear-gradient(#fcfdfb,#f6f8f4)}


.life-card>header>div{flex:1}


.life-card h2{font:15px Georgia;margin:0}


.life-card header small{font-size:10.5px;color:var(--muted)}


.life-card header button{border:0;background:none;color:var(--green);font-size:11px}


.life-card header>span{font-size:11px;color:var(--muted)}


.life-queue-card{margin-top:0}


.life-queue-card>header{min-height:78px;padding:12px 17px}


.life-queue-card>header h2{font-size:18px}


.life-queue-filters{display:flex;gap:14px;margin-left:auto}


.life-queue-filters select{height:42px;min-width:250px;border:1px solid var(--line);border-radius:4px;background:#fff;padding:0 38px 0 13px;color:var(--ink)}


.life-queue-card .life-table-wrap{margin:20px 17px;border:1px solid var(--line);border-radius:5px}


.life-queue-card .life-table th{padding:12px 15px}


.life-queue-card .life-table td{padding:11px 15px;white-space:normal}


.life-client-cell{display:flex;align-items:center;gap:10px;min-width:280px}


.life-client-avatar{width:38px;height:38px;border-radius:50%;display:grid;place-items:center;flex:none;color:#fff;background:linear-gradient(145deg,#dba3c7,#90549c);font-family:Georgia}


.life-client-cell b,.life-client-cell small{display:block}


.life-contact-tag{display:inline-block;margin-left:7px;padding:2px 8px;border:1px solid #d9a319;border-radius:4px;background:#fff8df;color:#805900;font-size:10px;font-weight:600}


.life-queue-actions{display:grid;gap:4px}


.life-queue-actions .life-btn{padding:6px 10px}


.life-queue-actions .life-link{border:1px solid var(--line);border-radius:4px;padding:6px 10px;color:var(--ink);font-weight:400;background:#fff}


.life-table-wrap{overflow:auto}


.life-table{width:100%;border-collapse:collapse;white-space:nowrap}


.life-table th{padding:8px 10px;background:#f1f5ef;color:var(--green);font-size:10px;text-transform:uppercase;letter-spacing:.6px;text-align:left;border-bottom:1px solid var(--line)}


.life-table td{padding:8px 10px;border-bottom:1px solid #e9ede6;vertical-align:middle}


.life-table tr:last-child td{border-bottom:0}


.life-table tbody tr:hover{background:#fafcf8}


.life-table .num{text-align:right}


.life-link{color:var(--green);font-weight:600;border:0;background:none;padding:0}


.life-sub{display:block;color:var(--muted);font-size:10px;margin-top:2px}


.life-empty{padding:36px 14px;text-align:center;color:var(--muted)}


.life-badge{display:inline-block;padding:2px 7px;border-radius:3px;border:1px solid #dce1da;background:#f0f2ef;color:#657163;font-size:10px;font-weight:600}


.life-badge.green{background:#edf6e0;border-color:#cfe5b0;color:var(--green)}


.life-badge.red{background:#fbedeb;border-color:#efc7c1;color:var(--red)}


.life-badge.amber{background:#fdf3e0;border-color:#ebd3a6;color:var(--amber)}


.life-badge.blue{background:#eaf1f8;border-color:#c4d8ec;color:var(--blue)}


.life-attention{list-style:none;margin:0;padding:5px 13px}


.life-attention li{padding:9px 0;border-bottom:1px solid #e9ede6;display:flex;gap:9px}


.life-attention li:last-child{border:0}


.life-attention i{width:8px;height:8px;border-radius:50%;background:var(--amber);margin-top:5px;flex:none}


.life-attention b,.life-attention small{display:block}


.life-attention small{color:var(--muted);margin-top:2px}


.life-form-area{padding:16px}


.life-form-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;margin-bottom:12px}


.life-form-grid label{font-size:10px;letter-spacing:.6px;text-transform:uppercase;color:var(--muted)}


.life-form-grid select{display:block;width:100%;height:37px;margin-top:5px;border:1px solid var(--line);border-radius:4px;background:#fff;padding:0 10px}


.life-note{border:1px solid #ebd3a6;background:#fdf3e0;color:#795400;padding:10px 12px;border-radius:4px;margin-bottom:12px}


.life-action-stack{display:flex;gap:5px;justify-content:flex-end}


.life-action-stack .life-btn{padding:5px 9px}


.life-action-stack .primary{background:var(--green);border-color:var(--green);color:#fff}


.life-master-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;padding:13px}


.life-master-box{border:1px solid var(--line);background:#fff;border-radius:4px}


.life-master-box h3{font:14px Georgia;margin:0;padding:9px 10px;border-bottom:1px solid var(--line)}


.life-master-box ul{list-style:none;padding:8px 10px;margin:0}


.life-master-box li{padding:5px 0;border-bottom:1px solid #e9ede6}


.life-master-box li:last-child{border:0}


.life-shade{position:fixed;inset:0;background:rgba(13,30,18,.35);z-index:70}


.life-drawer{position:fixed;z-index:71;right:0;top:0;width:min(680px,92vw);height:100vh;background:var(--paper);transform:translateX(101%);transition:.22s;box-shadow:-5px 0 22px rgba(0,0,0,.16);overflow:auto}


.life-drawer.open{transform:none}


.life-drawer>header{height:65px;position:sticky;top:0;background:var(--forest);color:#fff;padding:13px 17px;display:flex;align-items:center;z-index:2}


.life-drawer>header div{flex:1}


.life-drawer h2{margin:0;font:18px Georgia}
.life-drawer>header h2{color:#fff}


.life-drawer header small{color:#cfe0d1}


.life-drawer header button{border:0;background:none;color:#fff;font-size:25px}


.life-drawer-body,.life-drawer #drawerBody{padding:15px}


.life-detail-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin-bottom:13px}


.life-detail{background:#fff;border:1px solid var(--line);padding:10px;border-radius:4px}


.life-detail small,.life-detail b{display:block}


.life-detail small{color:var(--muted);font-size:9px;text-transform:uppercase;margin-bottom:4px}


.life-drawer-section{background:#fff;border:1px solid var(--line);margin-bottom:12px}


.life-drawer-section h3{font:14px Georgia;margin:0;padding:9px 11px;border-bottom:1px solid var(--line)}


.life-toast{position:fixed;right:20px;bottom:20px;background:var(--forest);color:#fff;padding:10px 14px;border-radius:4px;z-index:90;opacity:0;pointer-events:none;transform:translateY(8px);transition:.2s}


.life-toast.show{opacity:1;transform:none}


@media(max-width:1100px){.life-kpis{grid-template-columns:repeat(3,1fr)}


.life-filter-grid{grid-template-columns:repeat(2,1fr)}


.life-filter-buttons{grid-column:span 2}


.life-two-col{grid-template-columns:1fr}

}


@media(max-width:720px){.life-side{position:fixed;transform:translateX(-100%)}


.life-side.mobile-open{transform:none;width:220px}


.life-edge{left:5px;top:70px}


.life-main{width:100%}


.life-topbar{padding:0 13px}


.life-top-actions>.life-btn{display:none}


.life-user div{display:none}


.life-filter-card{margin:12px}


.life-view{padding:3px 12px 28px}


.life-filter-grid{grid-template-columns:1fr}


.life-filter-buttons{grid-column:auto}


.life-kpis{grid-template-columns:repeat(2,1fr)}


.life-detail-grid{grid-template-columns:repeat(2,1fr)}

}


@media print{.life-side,.life-edge,.life-top-actions,.life-filter-buttons{display:none!important}


.life-view{display:none!important}


.life-view.active{display:block!important}


.life-main{width:100%}


.life-topbar{position:static}


.life-filter-card{margin:8px 0}


.life-view{padding:0}


.life-card{break-inside:avoid}


.life-table-wrap{overflow:visible}

}


.life-mobile{display:inline-grid;min-width:92px;cursor:help;font-variant-numeric:tabular-nums}


.life-mobile .full{display:none;color:var(--green);font-weight:600}


.life-mobile:hover .masked,.life-mobile:focus .masked{display:none}


.life-mobile:hover .full,.life-mobile:focus .full{display:inline}


.life-mobile:focus{outline:1px dotted var(--gold);outline-offset:2px}


.life-table tr[data-branch-row],.life-table tr[data-client-row]{cursor:pointer}


