.life-queue-filters{display:grid;grid-template-columns:150px 150px minmax(190px,1fr) minmax(210px,1fr);gap:10px;align-items:end;width:100%;min-width:0;margin:0}
.life-queue-filters .life-client-filter{grid-column:1/-1;grid-row:2}
.life-queue-filters .life-client-filter select{height:44px;font-size:12px;border-color:#b9c8b7;background:#fff}
.life-queue-filters label{display:block;min-width:0;font-size:9px;color:#718074;text-transform:uppercase}
.life-queue-filters label input,.life-queue-filters label select{display:block;width:100%;height:42px;min-width:0;border:1px solid var(--line);border-radius:4px;background:#fff;padding:0 11px;color:var(--ink);font-size:11px;text-transform:none}
.life-queue-filters label select{padding-right:32px}

/* Followup type and latest activity panels */
.life-dashboard-lower{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:14px}
.life-dashboard-lower>.life-card{min-height:430px;margin:0}
.life-dashboard-lower>.life-card>header{height:54px;min-height:54px;padding:10px 16px}
.life-dashboard-lower>.life-card>header h2{font-size:17px}
.life-type-bars{padding:15px 18px}
.life-type-bar{display:grid;grid-template-columns:150px 1fr 34px;gap:10px;align-items:center;margin:12px 0;font-size:11px}
.life-type-bar>span{text-align:right;color:#34483b}
.life-type-bar>i{height:17px;display:block;background:#edf1eb;border-radius:2px;overflow:hidden}
.life-type-bar>i>b{height:100%;display:block;background:#1c6037;border-radius:2px}
.life-type-bar>strong{text-align:right;color:#153f27}
.life-activity-list{position:relative;padding:12px 18px 18px 35px}
.life-activity-list:before{content:"";position:absolute;left:25px;top:16px;bottom:20px;width:2px;background:#d8e0d5}
.life-activity-item{position:relative;width:100%;display:block;border:0;background:none;text-align:left;padding:8px 6px 9px 14px;color:inherit;cursor:pointer}
.life-activity-item:hover{background:#f4f8f2}
.life-activity-item>i{position:absolute;left:-17px;top:13px;width:12px;height:12px;border:2px solid #fff;border-radius:50%;background:#84c63f;box-shadow:0 0 0 1px #cbd8c6}
.life-activity-item small,.life-activity-item b,.life-activity-item em{display:block}
.life-activity-item small{color:#778579;font-size:9.5px}
.life-activity-item b{margin:3px 0;color:#1d3023;font-size:12px}
.life-activity-item b .life-badge{margin-left:5px}
.life-activity-item em{font-style:normal;color:#56645a;font-size:10.5px}
@media(max-width:1250px){.life-queue-filters{grid-template-columns:1fr 1fr}.life-queue-filters .life-client-filter{grid-column:1/-1;grid-row:auto}.life-dashboard-lower{grid-template-columns:1fr}}
@media(max-width:760px){.life-queue-filters{grid-template-columns:1fr 1fr}.life-client-filter{grid-column:1/-1}.life-dashboard-lower>.life-card{min-height:0}}

/* ================================================================
   ASSET MASTER VISUAL SKIN — v3.0.54
   Presentation only. No data or behaviour is changed.
   ================================================================ */
#lifeHealthcareApp{
  --forest:#15552f;--green:#1b6037;--leaf:#eef7e4;--gold:#d39b16;
  --paper:#f3f7f1;--card:#ffffff;--line:#d6e0d3;--ink:#102419;
  --muted:#789083;min-height:100vh;background:var(--paper);font-size:13px
}

/* Dark green header across both sections */
.life-brand{
  height:88px;padding:15px 20px;background:linear-gradient(115deg,#123f24,#1e6840);
  border-bottom:4px solid var(--gold);gap:14px
}
.life-mark{width:52px;height:52px;border-radius:12px;background:#8ccc36;color:#173c20;font-size:25px;box-shadow:0 3px 8px rgba(0,0,0,.18)}
.life-brand-text b{font:700 21px Georgia;color:#fff}.life-brand-text small{font-size:10px;color:#d7efb5;letter-spacing:1.5px}
.life-topbar{
  height:88px;background:linear-gradient(110deg,#154d2c,#2f8559);color:#fff;
  border-bottom:4px solid var(--gold);padding:0 22px
}
.life-topbar h1{font-size:22px;color:#fff}.life-topbar small,.life-clock small,.life-user small{color:#d9e9dd}
.life-clock{border-right-color:rgba(255,255,255,.28)}.life-clock b{color:#fff;font-size:15px}
.life-user{border-left:0;padding:6px 13px;border:1px solid rgba(255,255,255,.28);border-radius:24px;background:rgba(255,255,255,.08)}
.life-user>span{background:var(--gold);color:#173b22;width:39px;height:39px}.life-user b{color:#fff}
.life-topbar .life-btn{color:#fff;border-color:rgba(255,255,255,.3);background:rgba(255,255,255,.09);border-radius:8px;padding:9px 14px}
.life-healthcare-button{background:var(--gold);border-color:var(--gold);color:#173b22;border-radius:18px;box-shadow:none}
.life-healthcare-button:hover{background:#e2ad29;border-color:#e2ad29;color:#173b22}

/* White rounded Asset Master sidebar */
.life-side{width:272px;flex-basis:272px;background:#fff;color:#183326;border-right:2px solid var(--gold)}
.life-side nav{height:calc(100vh - 129px);padding:18px 12px;background:#fff}
.life-side nav p{margin:7px 12px 8px;padding:13px 6px 7px;border-top:0;border-bottom:1px solid #d7e0d4;color:#799086;font-weight:800;letter-spacing:1.6px}
.life-side nav p:first-child{border-bottom:1px solid #d7e0d4}
.life-side nav button{
  width:100%;min-height:51px;margin:4px 0;padding:8px 11px;border:0;border-left:4px solid transparent;
  border-radius:0 13px 13px 0;color:#183326;background:#fff;gap:10px
}
.life-side nav button:hover{background:#f1f7ec;color:#123f24}
.life-side nav button.active{background:#e9f3dc;color:#123f24;border-left-color:#237343;font-weight:700}
.life-side nav button span{display:grid;place-items:center;width:38px;height:38px;border-radius:11px;background:#edf5e7;color:#1e673b;font-size:16px}
.life-side nav button b{font-size:13px;font-weight:600}.life-side nav button i{background:#f4f8f2;border:1px solid #d2ded0;color:#315c40;padding:3px 8px;border-radius:14px}
.life-side nav button.active i{background:#fff}.life-side-foot{height:41px;background:#fff;border-top:1px solid #d7e0d4;color:#708878}
.life-edge{left:262px;top:51%;width:31px;height:62px;border-color:var(--gold);border-radius:0 14px 14px 0;color:#294b36;font-size:18px;box-shadow:1px 2px 5px rgba(20,55,30,.12)}
.life-side.collapsed+.life-edge{left:50px}

/* Main surface and cards */
.life-main{background:#f4f8f2}.life-filter-card{margin:13px 22px 10px;border-radius:12px;border:1px solid #d2ded0;border-top:3px solid var(--gold);box-shadow:0 2px 8px rgba(18,63,36,.06)}
.life-filter-title{padding:11px 15px}.life-filter-grid{padding:12px 15px}.life-filter-grid input,.life-filter-grid select{height:38px;border-radius:7px}
.life-view{padding:6px 22px 28px}.life-card{border-radius:13px;border-color:#d4dfd1;box-shadow:0 2px 8px rgba(16,55,30,.06);overflow:hidden}
.life-card>header{min-height:56px;padding:11px 15px;background:#fff}.life-card>header h2{font:700 18px Georgia;color:#153f26}.life-card header small{color:#7a8e80}
.life-btn{border-radius:8px}.life-btn.primary{background:#175b34;border-color:#175b34}.life-action-stack .life-btn{border-radius:9px;font-weight:700}

/* Asset Register table treatment */
.life-table-wrap{border:1px solid #d3dfd0;border-radius:9px;overflow:auto;background:#fff}
.life-table{font-size:12px}.life-table th{
  background:#185a34;color:#fff;padding:9px 10px;border-right:1px solid rgba(255,255,255,.65);
  border-bottom:0;font-size:9.5px;font-weight:800;letter-spacing:.55px
}
.life-table th:last-child{border-right:0}.life-table td{padding:8px 10px;border-right:1px solid #dbe4d8;border-bottom:1px solid #e1e8df}
.life-table td:last-child{border-right:0}.life-table tbody tr:nth-child(even){background:#f7faf5}.life-table tbody tr:hover,.life-table tr[data-client-row]:hover{background:#edf6e6}
.life-link{color:#07582f;font-weight:700}.life-table .life-btn,.life-table .life-action-stack .life-btn{border-radius:10px;padding:5px 10px}
.life-table .life-btn.primary{background:#155d35;color:#fff;border-color:#155d35}.life-badge{border-radius:12px;padding:3px 9px}
.life-badge.green{background:#e9f5e5}.life-badge.blue{background:#e7f0fb}.life-badge.amber{background:#fff3dc}.life-badge.red{background:#fceae7}

/* KPI cards */
.life-dashboard-kpis,.life-kpis{gap:12px}.life-dashboard-kpi,.life-kpi{border-radius:12px;box-shadow:0 2px 8px rgba(18,63,36,.06)}
.life-dashboard-kpi:before,.life-kpi:before{width:5px}.life-dashboard-kpi:hover{transform:translateY(-2px);border-color:#a6bca6}

/* Diet Chart Desk specific compact register */
#view-dietcharts .life-card>header{border-bottom:0}
#view-dietcharts .life-table-wrap{margin:0;border-width:1px 0 0;border-radius:0}
#view-dietcharts .life-table td{height:46px}
#view-dietcharts .life-table td:first-child .life-link{font-size:13px}
#view-dietcharts .life-table td:last-child .life-btn{display:inline-flex;background:#155d35;color:#fff;border-color:#155d35;font-weight:700}

/* Keep popups in the same visual family */
.life-popup,.life-drawer{border-radius:14px}.life-popup>header,.life-drawer>header{background:linear-gradient(110deg,#154d2c,#277448);border-bottom:3px solid var(--gold)}
.life-popup>header h2,.life-popup>header small,.life-drawer>header h2,.life-drawer>header small{color:#fff}

@media(max-width:900px){
  .life-topbar{height:74px;padding:0 12px}.life-brand{height:74px}.life-side{position:fixed;width:272px;transform:translateX(-100%)}
  .life-side.mobile-open{transform:translateX(0)}.life-edge{left:0}.life-page-heading h1{font-size:17px}.life-top-actions .life-clock{display:none}
}

