/* ==============================================================
   LIFE FOLLOWUP MASTER — CENTERED LOGO WHEN SIDEBAR IS COLLAPSED
   ============================================================== */

/* Expanded sidebar remains without the old brand block */
#lifeHealthcareApp .life-side:not(.collapsed)::before{
  display:none;
}

/* Show only the LIFE "L" mark when the sidebar is collapsed */
#lifeHealthcareApp .life-side.collapsed::before{
  content:"L";
  position:absolute;
  top:13px;
  left:50%;
  transform:translateX(-50%);
  width:36px;
  height:36px;
  display:grid;
  place-items:center;
  border-radius:9px;
  background:#8cc63f;
