  function rebuildFollowupDisplayIds(){
    const rows=(DATA.feedbacks||[]).slice().sort((a,b)=>
      String(a.creation||a.followup_date||a.name||"").localeCompare(
        String(b.creation||b.followup_date||b.name||"")
      )
    );

    const key=rows.map(r=>String(r.name||"")+"|"+String(r.modified||r.creation||"")).join("||");
    if(key===FOLLOWUP_DISPLAY_ID_CACHE_KEY)return;

    FOLLOWUP_DISPLAY_ID_CACHE_KEY=key;
    FOLLOWUP_DISPLAY_ID_CACHE=new Map();

    const used=new Set();

    // Preserve any usable 5-digit suffix already present in legacy names.
    rows.forEach(r=>{
      const raw=String(r.name||"");
      const m=raw.match(/(\d{5})$/);
      if(!m)return;
      const n=Number(m[1]);
      if(!n||used.has(n))return;
      used.add(n);
      FOLLOWUP_DISPLAY_ID_CACHE.set(raw,"CF-"+String(n).padStart(5,"0"));
    });

    // Broken names ending in ##### get the next free clean number.
    let next=1;
    rows.forEach(r=>{
      const raw=String(r.name||"");
      if(!raw||FOLLOWUP_DISPLAY_ID_CACHE.has(raw))return;
      while(used.has(next))next++;
      used.add(next);
      FOLLOWUP_DISPLAY_ID_CACHE.set(raw,"CF-"+String(next).padStart(5,"0"));
      next++;
    });
  }

