  function invoiceClientMobile(invoice){
    if(!invoice)return "";

    // 1. Direct mobile fields if a deployment has them.
    const direct=invoice.custom_client_mobile_no
      ||invoice.mobile_no
      ||invoice.contact_mobile;
    if(direct)return direct;

    // 2. Exact linked Patient ID.
    const patientId=String(invoice.patient||"").trim();
    let patient=patientId
      ?DUES_PATIENT_CACHE.get(patientId)
        ||(DATA.patients||[]).find(p=>p.name===patientId)
      :null;

    // 3. Exact displayed Patient / Customer name.
    if(!patient){
      const names=[
        invoice.patient_name,
        invoice.customer_name,
        invoice.customer
      ].filter(Boolean);

      for(const name of names){
        const key=duesPersonKey(name);
        patient=DUES_PATIENT_NAME_CACHE.get(key)
          ||(DATA.patients||[]).find(p=>
            duesPersonKey(p.patient_name)===key
            ||duesPersonKey(p.first_name)===key
            ||duesPersonKey(p.name)===key
          );
        if(patient)break;
      }
    }

    return patient&&(patient.mobile||patient.phone)||"";
  }
