  function renderCorrectDues(){
    let from=$("#lifeFrom")?$("#lifeFrom").value:"";
    let to=$("#lifeTo")?$("#lifeTo").value:"";

    if(!from||!to){
      const bd=businessDates();
      from=from||bd[0];
      to=to||bd[1];
      if($("#lifeFrom"))$("#lifeFrom").value=from;
      if($("#lifeTo"))$("#lifeTo").value=to;
    }

    const periodLabel=fmtDate(from)+" to "+fmtDate(to);

    // DUES_DATA is fetched from Sales Invoice using posting_date between
    // the selected Master From/To, so every KPI below is filter-wise.
    const source=DUES_DATA_READY?DUES_DATA:visible.invoices;
    const invoices=source
      .filter(i=>num(i.docstatus)===1)
      .sort((a,b)=>String(b.posting_date||"").localeCompare(String(a.posting_date||"")));

    const invoiceValue=i=>num(i.rounded_total)||num(i.grand_total);
    const due=invoices.filter(i=>num(i.outstanding_amount)>0);

    const submittedTotal=invoices.reduce((s,i)=>s+invoiceValue(i),0);
    const pendingTotal=due.reduce(
      (s,i)=>s+Math.max(0,num(i.outstanding_amount)),
      0
    );
    const collectedTotal=invoices.reduce((s,i)=>{
      const total=invoiceValue(i);
      const pending=Math.max(0,num(i.outstanding_amount));
      return s+Math.max(0,total-pending);
    },0);

    const collectedInvoiceCount=invoices.filter(i=>{
      const total=invoiceValue(i);
      return Math.max(0,total-Math.max(0,num(i.outstanding_amount)))>0;
    }).length;

    const rate=submittedTotal
      ?Math.round(collectedTotal/submittedTotal*100)
      :0;

    const billing=$("#billingKpis");
    if(billing){
      billing.innerHTML=
        kpi(
          "Submitted invoice total",
          money(submittedTotal),
          invoices.length+" invoice(s) · Invoice Date "+periodLabel,
          "blue"
        )+
        kpi(
          "Pending dues",
          money(pendingTotal),
          due.length+" invoice(s) with live balance · "+periodLabel,
          "red"
        )+
        kpi(
          "Collected against invoices",
          money(collectedTotal),
          collectedInvoiceCount+" invoice(s) collected/partly collected · "+periodLabel
        )+
        kpi(
          "Collection rate",
          rate+"%",
          "Collected ÷ submitted invoice total · "+periodLabel,
          "amber"
        );
    }

    const rows=due.map(i=>{
      const value=invoiceValue(i);
      const pending=Math.max(0,num(i.outstanding_amount));
      const paid=Math.max(0,value-pending);

      return '<tr>'
        +'<td>'+recordButton("Sales Invoice",i.name)+'</td>'
