  async function openClientHistory(id){
    if(!id)return toast('Client not found');

    historyClientId=id;
    historyLive=null;

    const requestedId=id;
    const cached=cachedHistoryData(id);
    const popup=$("#branchPopup");

    $("#branchPopupShade").hidden=false;
    popup.classList.add("open");
    popup.setAttribute("aria-hidden","false");

    // IMPORTANT: show the data already loaded by Followup Master immediately.
    // Previously History stayed on the Loading screen until six backend queries
    // (and a practitioner lookup) finished. A slow query could therefore leave
    // the user looking at Loading for 25-50 seconds.
    if(cached && cached.p){
      historyLive=cached;
      paintClientHistoryPattern(cached);
    }else{
      $("#branchPopupTitle").textContent=cached.pname||id;
      $("#branchPopupSub").textContent="Loading client history…";
      $("#branchPopupBody").innerHTML='<div class="life-empty">Loading client history…</div>';
    }

    // Refresh the already-visible popup in the background with complete live data.
    // Each history section has a short timeout and Promise.allSettled means one
    // unavailable doctype cannot block all the other history sections.
    try{
      const live=await fetchClientHistory(id);

      // Ignore a late response if the user has opened another client's history
      // or closed this popup in the meantime.
      if(historyClientId!==requestedId || !popup.classList.contains('open'))return;

      historyLive=live;
      paintClientHistoryPattern(live);

      // Practitioner name hydration is useful but must never block History.
      const patient=live.p||{};
      Promise.resolve(ensurePractitionerName(patient.custom_employee_id||patient.custom_manager_name))
        .then(()=>{
          if(historyClientId===requestedId && popup.classList.contains('open')){
            paintClientHistoryPattern(live);
          }
        })
        .catch(()=>{});
    }catch(e){
      if(historyClientId!==requestedId || !popup.classList.contains('open'))return;

      // If cached data was already displayed, keep it visible and show only a
      // small warning instead of replacing the entire History with an error.
      if(cached && cached.p){
        const body=$("#branchPopupBody");
        if(body){
          body.insertAdjacentHTML('afterbegin','<div class="life-alert">Live history refresh could not finish. Showing already loaded data. '+esc(e.message||e)+'</div>');
        }
      }else{
        $("#branchPopupBody").innerHTML='<div class="life-alert">'+esc(e.message||e)+'</div>';
      }
    }
  }
