  async function loadFollowupDietDocuments(){
    const hidden=$("#dietPdfSelect"),
          search=$("#dietPdfSearch"),
          results=$("#dietPdfResults"),
          toggle=$("#dietPdfToggle"),
          selectedLabel=$("#dietPdfSelectedLabel"),
          status=$("#dietPdfStatus");

    if(!hidden||!search||!results)return;

    const view=$("#viewDietPdf"),send=$("#sendDietWhatsapp");

    hidden.value='';
    hidden.dataset.selectedUrl='';
    search.value='';
    results.hidden=true;
    results.innerHTML='';
    if(selectedLabel)selectedLabel.textContent='';

    if(view)view.disabled=true;
    if(send)send.disabled=true;
    if(status)status.textContent='Loading permitted Diet records…';

    let dietRows=[];

    try{
      dietRows=(await call('frappe.client.get_list',{
        doctype:'Diet',
        fields:['name','name1','posting_date','uploaded_by','modified','creation'],
        order_by:'posting_date desc, modified desc',
        limit_page_length:1000
      },12000))||[];

      DATA.diets=(DATA.diets||[])
        .concat(dietRows)
        .filter((row,index,all)=>
          row&&row.name&&
          all.findIndex(x=>x&&x.name===row.name)===index
        );
    }catch(e){
      ('Diet Link search list failed', e, void 0);
      search.disabled=true;

      if(status){
        status.textContent=isPermissionError(e)
          ?'Diet Read permission is not assigned to your ERPNext role.'
          :'Diet records could not be loaded: '+(e&&e.message?e.message:e);
      }
      return;
    }

    dietRows=dietRows
      .filter(row=>row&&row.name)
      .sort((a,b)=>{
        const ad=String(a.posting_date||a.modified||a.creation||'');
        const bd=String(b.posting_date||b.modified||b.creation||'');
        return bd.localeCompare(ad);
      });

    if(!dietRows.length){
      search.disabled=true;
      search.placeholder='No Diet records available';
      if(status)status.textContent='No permitted Diet records were found.';
      return;
    }

    search.disabled=false;

    if(status){
      status.textContent=dietRows.length+
        ' Diet record(s) available. Click the field or ▼ to select, or type to search.';
    }

    function rowTitle(row){
      return String(row.name1||row.name||'').trim();
    }

    function rowMeta(row){
      return [
        row.name!==row.name1?row.name:'',
        row.posting_date?fmtDate(row.posting_date):'',
        row.uploaded_by||''
      ].filter(Boolean).join(' · ');
    }

    function searchable(row){
      return lower([
        row.name,
        row.name1,
        row.posting_date,
        row.uploaded_by
      ].filter(Boolean).join(' '));
    }

    function renderResults(query){
      const q=lower(String(query||'').trim());

      let rows=q
        ?dietRows.filter(row=>searchable(row).includes(q))
        :dietRows.slice();

      rows=rows.slice(0,20);

      if(!rows.length){
        results.innerHTML='<div class="diet-link-empty">No matching Diet record</div>';
        results.hidden=false;
        return;
      }

      results.innerHTML=rows.map(row=>
        '<button type="button" class="diet-link-option" data-diet-link="'+esc(row.name)+'">'
          +'<b>'+esc(rowTitle(row))+'</b>'
          +'<small>'+esc(rowMeta(row)||row.name)+'</small>'
        +'</button>'
      ).join('');

      results.hidden=false;
    }

    async function selectDiet(dietName){
      const row=dietRows.find(x=>x.name===dietName);
      if(!row)return;

      hidden.value=row.name;
      hidden.dataset.selectedUrl='';
      search.value=rowTitle(row);
      results.hidden=true;
      results.innerHTML='';

      if(selectedLabel){
        selectedLabel.textContent='Linked Diet: '+row.name;
      }

      if(view)view.disabled=true;
      if(send)send.disabled=true;
      if(status)status.textContent='Loading linked Diet '+row.name+'…';

      try{
        const doc=await call('frappe.client.get',{
          doctype:'Diet',
          name:row.name
        },12000);

        const files=(Array.isArray(doc.document)?doc.document:[])
          .map((child,index)=>{
            const url=childValue(
              child,
              ['document','file','attachment','attach','file_url','document_url']
            );

            if(!url)return null;

            const label=
              childValue(
                child,
                ['document_name','title','template','template_name','diet_template']
              )||
              String(url).split('/').pop()||
              ('Diet file '+(index+1));

            return {
              url:url,
              label:label,
              diet:doc.name,
              date:doc.posting_date
            };
          })
          .filter(Boolean);

        if(!files.length){
          if(status){
            status.textContent=
              'Diet '+doc.name+
              ' selected. No attached file found in its Document child table.';
          }
          return;
        }

        const first=files[0];
        hidden.dataset.selectedUrl=first.url;

        if(view)view.disabled=false;
        if(send)send.disabled=false;

        if(status){
          status.textContent=
            'Diet '+doc.name+
            ' linked · '+files.length+
            ' attached file(s) · '+first.label;
        }
      }catch(e){
        ('Linked Diet record could not be opened', row.name, e, void 0);

        if(status){
          status.textContent=isPermissionError(e)
            ?'Diet '+row.name+' is selected, but your role cannot open the record.'
            :'Diet '+row.name+' could not be loaded: '+(e&&e.message?e.message:e);
        }
      }
    }

    function openDietLinkOptions(){
      if(search.disabled)return;
      renderResults(search.value);
    }

    search.addEventListener('focus',openDietLinkOptions);
    search.addEventListener('click',openDietLinkOptions);

    if(toggle){
      toggle.addEventListener('mousedown',function(e){
        e.preventDefault();
      });
      toggle.addEventListener('click',function(e){
        e.preventDefault();
        e.stopPropagation();
        if(results.hidden){
          search.focus();
          renderResults(search.value);
        }else{
          results.hidden=true;
        }
      });
    }

    search.addEventListener('input',function(){
      hidden.value='';
      hidden.dataset.selectedUrl='';

      if(selectedLabel)selectedLabel.textContent='';
      if(view)view.disabled=true;
      if(send)send.disabled=true;

      renderResults(search.value);
    });

    results.addEventListener('click',function(e){
      const btn=e.target.closest('[data-diet-link]');
      if(!btn)return;
      selectDiet(btn.dataset.dietLink);
    });

    document.addEventListener('click',function(e){
      if(!e.target.closest('.diet-link-wrap')){
        results.hidden=true;
      }
    },{once:false});

    if(view){
      view.onclick=()=>{
        const url=hidden.dataset.selectedUrl||'';
        if(!url)return toast('Selected Diet record has no attached file');
        window.open(url,'_blank','noopener');
      };
    }

    if(send){
      send.onclick=()=>{
        const url=hidden.dataset.selectedUrl||'';
        if(!url)return toast('Selected Diet record has no attached file');
        if(!followClient)return toast('Select a client first');

        const digits=String(
          followClient.mobile||followClient.phone||''
        ).replace(/\D/g,'');

        const phone=digits.length===10?'91'+digits:digits;
