  function dietNum(v){const n=Number(v);return Number.isFinite(n)?n:0;}
  function dietRound(v,d){const p=Math.pow(10,d==null?1:d);return Math.round(dietNum(v)*p)/p;}
  function dietBuilderTimeOptions(selected){
    const out=[];
    for(let m=5*60;m<=23*60+30;m+=30){
      const h24=Math.floor(m/60),mm=m%60,ap=h24>=12?'PM':'AM',h=h24%12||12;
      out.push(h+':'+String(mm).padStart(2,'0')+' '+ap);
    }
    const wanted=selected==null?'7:00 AM':String(selected);
    if(wanted&&!out.includes(wanted))out.unshift(wanted);
    const blank='<option value="" '+(!wanted?'selected':'')+'>Select time</option>';
    return blank+out.map(t=>'<option value="'+esc(t)+'" '+(t===wanted?'selected':'')+'>'+esc(t)+'</option>').join('');
  }
  function dietBuilderFoodKey(food){
    return lower(String(food||''))
      .replace(/[\/_-]+/g,' ')
      .replace(/[^a-z0-9 ]+/g,' ')
      .replace(/\s+/g,' ')
      .trim();
  }
  function dietBuilderAutoTelugu(food){
    const key=dietBuilderFoodKey(food);
    if(!key)return '';
    if(DIET_TELUGU_FOOD[key])return DIET_TELUGU_FOOD[key];

    // Small normalisation layer for common diet-entry variations.
    const aliases={
      'waters':'water',
      'plain waters':'plain water',
      'boil egg':'boiled egg',
      'boil eggs':'boiled eggs',
      'egg omlet':'egg omelette',
      'egg omlette':'egg omelette',
      'omlet':'omelette',
      'omlette':'omelette',
      'chapathi':'chapati',
      'chapattis':'chapati',
      'rotis':'roti',
      'brownrice':'brown rice',
      'green salad':'mixed green salad',
      'sprout salad':'sprouts salad',
      'butter milk':'buttermilk',
      'coco water':'coconut water',
      'veg soup':'vegetable soup',
      'veg curry':'vegetable curry'
    };
    const alias=aliases[key];
    return alias&&DIET_TELUGU_FOOD[alias]?DIET_TELUGU_FOOD[alias]:'';
  }

  function dietSyncFoodTelugu(englishInput){
    if(!englishInput)return;
    const tr=englishInput.closest('tr');
    const telugu=tr&&tr.querySelector('.diet-b-food-te');
    if(!telugu||telugu.dataset.manual==='1')return;

    clearTimeout(englishInput._lifeFoodTeluguTimer);
    const requested=String(englishInput.value||'').trim();
    const local=dietBuilderAutoTelugu(requested);

    // Always replace the previous auto value. This prevents stale text such as
    // Jeera water -> జీలకర్ర నీళ్లు remaining after the English food becomes Water.
    if(local){
      telugu.value=local;
      telugu.dataset.autoTranslated='1';
      telugu.dataset.autoSource=requested;
      return;
    }

    // If the food is unknown locally, clear the old automatic Telugu value
    // instead of leaving an incorrect translation on screen.
    telugu.value='';
    delete telugu.dataset.autoTranslated;
    delete telugu.dataset.autoSource;

    if(!requested||DIET_REMOTE_TRANSLATION_AVAILABLE===false)return;

    englishInput._lifeFoodTeluguTimer=setTimeout(async()=>{
      const current=String(englishInput.value||'').trim();
      if(!current||current!==requested||telugu.dataset.manual==='1'||!tr.isConnected)return;
      try{
        const translated=await dietTranslateNoteToTelugu(requested);
        if(translated&&String(englishInput.value||'').trim()===requested&&telugu.dataset.manual!=='1'){
          telugu.value=translated;
          telugu.dataset.autoTranslated='1';
          telugu.dataset.autoSource=requested;
        }
      }catch(e){
        ('Diet food Telugu translation failed:', e, void 0);
      }
    },500);
  }

  function dietAutofillVisibleTeluguRows(){
    const body=$('#dietBuilderRows');
    if(!body)return;
    body.querySelectorAll('tr[data-diet-builder-row]').forEach(tr=>{
      const foodEn=tr.querySelector('.diet-b-food-en');
      const foodTe=tr.querySelector('.diet-b-food-te');
      if(foodEn&&foodTe&&foodTe.dataset.manual!=='1'){
        const auto=dietBuilderAutoTelugu(foodEn.value);
        if(auto){foodTe.value=auto;foodTe.dataset.autoTranslated='1';foodTe.dataset.autoSource=foodEn.value;}
      }

      const noteEn=tr.querySelector('.diet-b-note-en');
      const noteTe=tr.querySelector('.diet-b-note-te');
      if(noteEn&&noteTe&&String(noteEn.value||'').trim()&&!dietHasTeluguText(noteTe.value)){
        const local=dietLocalNoteToTelugu(noteEn.value);
        if(local){noteTe.value=local;noteTe.dataset.autoTranslated='1';}
        else dietScheduleNoteTranslation(noteEn);
      }
    });
  }

