  function dietDecodeHtmlEntities(value){
    const text=String(value||'');
    if(!text||!/[&][#a-zA-Z0-9]+;/.test(text))return text;
    const el=document.createElement('textarea');
    el.innerHTML=text;
    return el.value;
  }

  function dietNormalizeEnglishDietNote(value){
    let key=lower(String(value||'').trim())
      .replace(/[“”‘’]/g,'')
      .replace(/[^a-z0-9+%/\- ]+/g,' ')
      .replace(/\s+/g,' ')
      .trim();

    // Common typing mistakes seen while entering diet notes quickly.
    const wordFix={
      'closeing':'closing','clsoing':'closing','closng':'closing',
      'folow':'follow','follw':'follow','foloow':'follow',
      'dite':'diet','deit':'diet',
      'befor':'before','bfore':'before',
      'aftr':'after','aftre':'after',
      'brakfast':'breakfast','brekfast':'breakfast',
      'diner':'dinner'
    };
    key=key.split(' ').map(w=>wordFix[w]||w).join(' ');
    return key;
  }

  function dietHasTeluguText(value){
    return /[\u0C00-\u0C7F]/.test(String(value||''));
  }

  function dietLocalNoteToTelugu(value){
    const key=dietNormalizeEnglishDietNote(value);
    if(!key)return '';
    if(DIET_NOTE_TELUGU_FALLBACK[key])return DIET_NOTE_TELUGU_FALLBACK[key];

    // Useful composition rules for short diet notes entered by dieticians.
    const before=key.match(/^before\s+(.+)$/);
    const after=key.match(/^after\s+(.+)$/);
    const avoid=key.match(/^avoid\s+(.+)$/);
    const no=key.match(/^no\s+(.+)$/);
    const only=key.match(/^(.+)\s+only$/);
    const follow=key.match(/^follow\s+(?:this\s+|the\s+)?(.+)$/);
    const drink=key.match(/^drink\s+(.+)$/);

    const nouns={
      "breakfast":"అల్పాహారం","lunch":"మధ్యాహ్న భోజనం","dinner":"రాత్రి భోజనం",
      "food":"భోజనం","meal":"భోజనం","rice":"అన్నం","sugar":"షుగర్","sweets":"స్వీట్లు",
      "oil":"నూనె","salt":"ఉప్పు","curd":"పెరుగు","milk":"పాలు","tea":"టీ","coffee":"కాఫీ",
      "water":"నీరు","fruit":"పండు","fruits":"పండ్లు","snacks":"స్నాక్స్","snack":"స్నాక్",
