  async function dietTranslateNoteToTelugu(value){
    const text=String(value||'').trim();
    if(!text)return '';
    const key=lower(text).replace(/\s+/g,' ').trim();

    const local=dietLocalNoteToTelugu(text);
    if(local){
      DIET_NOTE_TRANSLATION_CACHE.set(key,local);
      return local;
    }
    if(DIET_NOTE_TRANSLATION_CACHE.has(key))return DIET_NOTE_TRANSLATION_CACHE.get(key);
    if(DIET_REMOTE_TRANSLATION_AVAILABLE===false)return '';

    try{
      const result=await call('life_translate_telugu',{text},10000);
      const configured=!(result&&(result.configured===0||result.configured===false||result.configured==='0'));
      if(!configured){
        DIET_REMOTE_TRANSLATION_AVAILABLE=false;
        if(!DIET_REMOTE_TRANSLATION_WARNED){
          DIET_REMOTE_TRANSLATION_WARNED=true;
          ('Diet Telugu API is not configured. Using local diet-note translations only.', void 0);
        }
        return '';
      }

      DIET_REMOTE_TRANSLATION_AVAILABLE=true;
      const translated=dietDecodeHtmlEntities(
        typeof result==='string' ? result : (result&&result.translated)||''
      ).trim();
      if(translated){
        DIET_NOTE_TRANSLATION_CACHE.set(key,translated);
        return translated;
      }
    }catch(e){
      // Stop retrying the same unconfigured/broken API on every keystroke.
      DIET_REMOTE_TRANSLATION_AVAILABLE=false;
      if(!DIET_REMOTE_TRANSLATION_WARNED){
        DIET_REMOTE_TRANSLATION_WARNED=true;
        ('Diet Telugu API unavailable; continuing with local diet-note translations.', e, void 0);
      }
    }
    return '';
  }

  function dietScheduleNoteTranslation(englishInput){
    if(!englishInput)return;
    const tr=englishInput.closest('tr');
    const telugu=tr&&tr.querySelector('.diet-b-note-te');
    if(!telugu)return;
    if(telugu.dataset.manual==='1'&&dietHasTeluguText(telugu.value))return;
    if(telugu.dataset.manual==='1'&&!dietHasTeluguText(telugu.value))delete telugu.dataset.manual;

    clearTimeout(englishInput._lifeTeluguTimer);
    const text=String(englishInput.value||'').trim();
    if(!text){
      if(telugu.dataset.manual!=='1')telugu.value='';
      return;
    }

    englishInput._lifeTeluguTimer=setTimeout(async()=>{
      const requested=String(englishInput.value||'').trim();
      if(!requested)return;
      if(telugu.dataset.manual==='1'&&dietHasTeluguText(telugu.value))return;
      if(telugu.dataset.manual==='1'&&!dietHasTeluguText(telugu.value))delete telugu.dataset.manual;
      const oldPlaceholder=telugu.getAttribute('placeholder')||'తెలుగు — ఆరోగ్య సమాచారం';
      telugu.setAttribute('placeholder','తెలుగులోకి మారుస్తోంది…');
      telugu.classList.add('diet-translating');
      try{
        const translated=await dietTranslateNoteToTelugu(requested);
        if(
          translated &&
          !(telugu.dataset.manual==='1'&&dietHasTeluguText(telugu.value)) &&
          String(englishInput.value||'').trim()===requested &&
          tr&&tr.isConnected
        ){
          telugu.value=translated;
          telugu.dataset.autoTranslated='1';
        }
      }finally{
        telugu.classList.remove('diet-translating');
        telugu.setAttribute('placeholder',oldPlaceholder);
      }
    },650);
  }
