  function dietBuilderTarget(){
    const p=followData&&followData.p||followClient||{};
    const weight=dietNum($('#dietWeightToday')?$('#dietWeightToday').value:(p.custom_weightin_kg||0))||dietNum(p.custom_weightin_kg);
    const height=dietNum(p.custom_heightin_cm);
    const dob=String(p.dob||'');
    const age=dob?Math.max(0,new Date().getFullYear()-Number(dob.slice(0,4))):0;
    const male=lower(p.sex).startsWith('m');
    if(!weight)return {weight:0,height,age,maintenance:0,targetCalories:0,targetProtein:0};
    let maintenance=0;
    if(height&&age){
      const bmr=10*weight+6.25*height-5*age+(male?5:-161);
      maintenance=Math.round(bmr*1.55);
    }else maintenance=Math.round(weight*28);
    const targetCalories=Math.max(1200,maintenance-500);
    const targetProtein=Math.round(weight*1.4);
    return {weight,height,age,maintenance,targetCalories,targetProtein};
  }
