    /*
      sep=, tells Microsoft Excel which separator to use even on PCs whose
      regional list separator is semicolon. UTF-8 BOM keeps Telugu readable.
    */
    const csv='\ufeffsep=,\r\n'+[DIET_CHART_FILE_HEADERS]
      .concat(dataRows)
      .map(row=>row.map(dietBuilderCsvEscape).join(','))
