  function dietBuilderCountDelimiter(line,delimiter){
    let count=0,quoted=false;
    const s=String(line||'');
    for(let i=0;i<s.length;i++){
      const c=s[i];
      if(c==='"'){
        if(quoted&&s[i+1]==='"'){i++;continue;}
        quoted=!quoted;
      }else if(!quoted&&c===delimiter){
        count++;
      }
    }
    return count;
  }

  function dietBuilderDetectDelimiter(text){
    const lines=String(text||'').replace(/^\uFEFF/,'').split(/\r?\n/)
      .map(x=>x.trim()).filter(Boolean).slice(0,6);
    const sample=lines.find(x=>!/^sep\s*=\s*./i.test(x))||'';
    const options=[',',';','\t','|'];
    let best=',',score=-1;
    options.forEach(d=>{
      const n=dietBuilderCountDelimiter(sample,d);
      if(n>score){score=n;best=d;}
    });
    return best;
  }

  function dietBuilderParseDelimited(text,delimiter){
    let input=String(text||'').replace(/^\uFEFF/,'');
    input=input.replace(/^sep\s*=\s*.\s*\r?\n/i,'');
    const rows=[];
    let row=[],cell='',quoted=false;

    for(let i=0;i<input.length;i++){
      const c=input[i];
      if(quoted){
        if(c==='"'&&input[i+1]==='"'){
          cell+='"';i++;
        }else if(c==='"'){
          quoted=false;
        }else{
          cell+=c;
        }
      }else if(c==='"'){
        quoted=true;
      }else if(c===delimiter){
        row.push(cell);cell='';
      }else if(c==='\n'){
        row.push(cell.replace(/\r$/,''));
        rows.push(row);row=[];cell='';
      }else{
        cell+=c;
      }
    }
    if(cell!==''||row.length){row.push(cell.replace(/\r$/,''));rows.push(row);}
    return rows.filter(r=>r.some(x=>String(x||'').trim()));
  }

  function dietBuilderParseCsv(text){
    const delimiter=dietBuilderDetectDelimiter(text);
    return dietBuilderParseDelimited(text,delimiter);
  }

  function dietBuilderNormalizeHeader(value){
    return String(value||'')
      .replace(/^\uFEFF/,'')
      .toLowerCase()
      .replace(/[—–_-]+/g,' ')
      .replace(/[()\[\]{}:/\\]+/g,' ')
      .replace(/[\u0C00-\u0C7F]+/g,' ')
      .replace(/[^a-z0-9]+/g,' ')
      .replace(/\s+/g,' ')
      .trim();
  }

  const DIET_IMPORT_HEADER_ALIASES={
    time:['time','meal time','timing'],
    food:['food item','food','item','meal','food item english'],
    food_telugu:['food item telugu','telugu name','telugu food','food telugu','food name telugu'],
    quantity:['quantity','qty'],
    unit:['unit','uom','quantity unit'],
    note:['note to client','note','client note','remarks','note english'],
    note_telugu:['note to client telugu','telugu note','client note telugu','note telugu'],
    kcal:['kcal','calories','calorie','cal'],
    protein:['protein','g protein'],
    carbs:['carbs','carbohydrates','carbohydrate'],
    fat:['fat','g fat'],
    fibre:['fibre','fiber','g fibre','g fiber']
  };

  function dietBuilderFindHeaderIndex(header,aliases){
    const normalized=(header||[]).map(dietBuilderNormalizeHeader);
    for(const alias of aliases){
      const wanted=dietBuilderNormalizeHeader(alias);
      const exact=normalized.indexOf(wanted);
      if(exact>=0)return exact;
    }
    for(let i=0;i<normalized.length;i++){
      const h=normalized[i];
      for(const alias of aliases){
        const wanted=dietBuilderNormalizeHeader(alias);
        if(wanted&&h&&(h.includes(wanted)||wanted.includes(h)))return i;
      }
    }
    return -1;
  }

  function dietBuilderBuildHeaderMap(header){
    const map={};
    Object.keys(DIET_IMPORT_HEADER_ALIASES).forEach(key=>{
      map[key]=dietBuilderFindHeaderIndex(header,DIET_IMPORT_HEADER_ALIASES[key]);
    });
    return map;
  }

  function dietBuilderFindHeaderRow(rows){
    const max=Math.min(10,rows.length);
    let best=null;
    for(let i=0;i<max;i++){
      const map=dietBuilderBuildHeaderMap(rows[i]);
      const score=['time','food','quantity'].reduce((n,k)=>n+(map[k]>=0?1:0),0)
        +['unit','note','food_telugu','note_telugu','kcal','protein'].reduce((n,k)=>n+(map[k]>=0?.25:0),0);
      if(!best||score>best.score)best={rowIndex:i,map,score};
    }
    return best&&best.score>=3?best:null;
  }

  function dietBuilderTemplateNutrition(food){
    const wanted=lower(String(food||'').trim());
    if(!wanted)return null;
    for(const template of DIET_BUILDER_TEMPLATES){
