        if(lower(String(r[1]||'').trim())===wanted){
          return {kcal:dietNum(r[7]),protein:dietNum(r[8]),carbs:dietNum(r[9]),fat:dietNum(r[10]),fibre:dietNum(r[11]),qty:dietNum(r[3]),unit:r[4]||'nos'};
        }
      }
    }
    return null;
  }

  function dietBuilderNormalizeImportedTime(value){
    let raw=String(value||'').trim();
    if(!raw)return '7:00 AM';

    // Excel can save a time as a fraction of a day, e.g. 0.3125 = 7:30 AM.
    if(/^0?\.\d+$/.test(raw)){
      const fraction=Number(raw);
      if(fraction>=0&&fraction<1){
        let total=Math.round(fraction*24*60);
        total=((total%(24*60))+(24*60))%(24*60);
        let h=Math.floor(total/60),min=total%60;
        const ap=h>=12?'PM':'AM';h=h%12||12;
        return h+':'+String(min).padStart(2,'0')+' '+ap;
      }
    }

    let m=raw.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
    if(m){
      let h=Number(m[1]);const min=m[2];
      if(h>=0&&h<=23){const ap=h>=12?'PM':'AM';h=h%12||12;return h+':'+min+' '+ap;}
    }

    m=raw.match(/^(\d{1,2}):(\d{2})\s*([ap])\.?m\.?$/i);
    if(m)return Number(m[1])+':'+m[2]+' '+m[3].toUpperCase()+'M';
    return raw;
  }

  async function dietBuilderImportCsv(file){
    if(!file)return;

    if(!/\.(csv|txt|tsv)$/i.test(file.name||'')){
      toast('Please upload the CSV/TSV downloaded from this Diet Chart Builder.');
      return;
    }

    try{
      const text=await file.text();
      const rows=dietBuilderParseCsv(text);
      if(!rows.length){toast('The uploaded file is empty.');return;}

      const headerInfo=dietBuilderFindHeaderRow(rows);
      if(!headerInfo){
        ('Diet CSV header not recognised:', rows.slice(0,3), void 0);
        toast('Diet file columns were not recognised. Required columns are Time, Food Item and Quantity. Download a fresh blank format and try again.');
        return;
      }

      const map=headerInfo.map;
      const cell=(r,key)=>map[key]>=0?String(r[map[key]]==null?'':r[map[key]]).trim():'';
      const data=[];

      rows.slice(headerInfo.rowIndex+1).forEach(r=>{
        const food=cell(r,'food');
        if(!food)return;
        const lib=dietBuilderTemplateNutrition(food);
        const qtyRaw=cell(r,'quantity');
        const unitRaw=cell(r,'unit');
        const foodTe=cell(r,'food_telugu')||dietBuilderAutoTelugu(food);
        const noteEn=cell(r,'note');
        const noteTe=cell(r,'note_telugu');

        const valueOrLibrary=(key,libraryKey)=>{
          const raw=cell(r,key);
          return raw!==''?Math.max(0,dietNum(raw)):Math.max(0,dietNum(lib&&lib[libraryKey]));
        };

        data.push([
          dietBuilderNormalizeImportedTime(cell(r,'time')),
          food,
          foodTe,
          qtyRaw!==''?Math.max(0,dietNum(qtyRaw)):Math.max(0,dietNum(lib&&lib.qty)||1),
          unitRaw||(lib&&lib.unit)||'nos',
          noteEn,
          noteTe,
          valueOrLibrary('kcal','kcal'),
          valueOrLibrary('protein','protein'),
          valueOrLibrary('carbs','carbs'),
          valueOrLibrary('fat','fat'),
          valueOrLibrary('fibre','fibre')
        ]);
      });

      if(!data.length){
        toast('No filled food rows were found. Make sure the Food Item column has values.');
        return;
      }

      const body=$('#dietBuilderRows');
      if(!body)return;
      body.innerHTML=data.map((r,i)=>dietBuilderRowHtml(r,i)).join('');

      body.querySelectorAll('tr[data-diet-builder-row]').forEach(tr=>{
        const foodTe=tr.querySelector('.diet-b-food-te');
        const noteTe=tr.querySelector('.diet-b-note-te');
        if(foodTe&&!dietHasTeluguText(foodTe.value))delete foodTe.dataset.manual;
        if(noteTe&&!dietHasTeluguText(noteTe.value))delete noteTe.dataset.manual;
      });
      dietAutofillVisibleTeluguRows();

      dietBuilderApplyLanguage();
      dietBuilderUpdate();
      toast(data.length+' diet row(s) uploaded successfully.');
    }catch(e){
      ('Diet chart file upload failed:', e, void 0);
      toast('Could not read this diet file. Download a fresh blank format, fill it in Excel, Save As CSV UTF-8, and upload again.');
    }
  }

