    const lines=['Hello '+(p.patient_name||p.first_name||p.name||'')+', your diet chart is ready.','Valid for: '+valid,''];
    rows.forEach(r=>{
      const food=mode==='Telugu only'?(r.food_telugu||r.food):(mode==='English only'?r.food:(r.food+(r.food_telugu?' / '+r.food_telugu:'')));
