  function initDietChartBuilder(){
    const box=$('#dietChartBuilder');if(!box)return;

    // Start with ONE BLANK ROW.  Do not pre-fill Jeera water, walnuts,
    // egg omelette, etc.  The dietician can choose a template explicitly.
    let blankIndex=DIET_BUILDER_TEMPLATES.findIndex(t=>lower(t&&t.name)==="custom blank");
    if(blankIndex<0)blankIndex=Math.max(0,DIET_BUILDER_TEMPLATES.length-1);
    const templateSelect=$('#dietChartTemplate');
    if(templateSelect)templateSelect.value=String(blankIndex);
    dietBuilderLoadTemplate(blankIndex);
    box.addEventListener('input',e=>{
      if(e.target.classList.contains('diet-b-food-en')){
        dietSyncFoodTelugu(e.target);
      }

      // As the user types an English client note, wait briefly and fill the
      // Telugu field below it. Manual Telugu edits are never overwritten.
      if(e.target.classList.contains('diet-b-note-en')){
        dietScheduleNoteTranslation(e.target);
      }

      if(e.target.classList.contains('diet-b-food-te')){
        if(dietHasTeluguText(e.target.value))e.target.dataset.manual='1';
        else delete e.target.dataset.manual;
      }
      if(e.target.classList.contains('diet-b-note-te')){
        if(dietHasTeluguText(e.target.value))e.target.dataset.manual='1';
        else delete e.target.dataset.manual;
      }
      dietBuilderUpdate();
    });
    box.addEventListener('change',()=>dietBuilderUpdate());
    box.addEventListener('click',e=>{const rm=e.target.closest('[data-remove-diet-builder-row]');if(rm){const tr=rm.closest('tr');if(tr)tr.remove();dietBuilderUpdate();}});
    $('#dietChartTemplate').onchange=e=>dietBuilderLoadTemplate(e.target.value);
    $('#dietResetTemplate').onclick=()=>dietBuilderLoadTemplate($('#dietChartTemplate').value);
    $('#dietAddRow').onclick=()=>{const body=$('#dietBuilderRows'),i=body.children.length;body.insertAdjacentHTML('beforeend',dietBuilderRowHtml(["7:00 AM","","",1,"nos","","",0,0,0,0,0],i));dietAutofillVisibleTeluguRows();dietBuilderApplyLanguage();dietBuilderUpdate();};
    $('#dietChartLanguage').onchange=()=>{dietBuilderApplyLanguage();dietBuilderUpdate();};
    $('#dietPreviewChart').onclick=dietBuilderPreview;
    $('#dietDownloadBlank').onclick=()=>dietBuilderDownloadCsv(true);
    $('#dietDownloadCurrent').onclick=()=>dietBuilderDownloadCsv(false);
    $('#dietUploadBtn').onclick=()=>$('#dietUploadCsv').click();
    $('#dietUploadCsv').onchange=async e=>{
      const input=e.target;
      await dietBuilderImportCsv(input.files&&input.files[0]);
      // Allow the same file to be selected again after correcting it in Excel.
      input.value='';
    };
    $('#dietSaveWhatsapp').onclick=saveDietBuilderAndSendWhatsapp;
    if($('#dietWeightToday')){
      const weightInput=$('#dietWeightToday');
      weightInput.setAttribute('min','0');
      weightInput.setAttribute('max','200');
      weightInput.addEventListener('input',function(){
        let value=Number(weightInput.value);
        if(weightInput.value!==''&&Number.isFinite(value)){
          if(value>200){
            weightInput.value='200';
            toast('Weight today cannot be above 200 kg');
          }else if(value<0){
            weightInput.value='0';
          }
        }
        dietBuilderUpdate();
      });
    }
    if($('#dietReviewDate')&&!$('#dietReviewDate').value)$('#dietReviewDate').value=$('#followupNext')?$('#followupNext').value:'';
    if($('#dietReviewedBy')&&currentEmployee)$('#dietReviewedBy').value=currentEmployee;
    dietBuilderApplyLanguage();dietBuilderUpdate();loadFollowupDietDocuments();
  }
  function initDietFollowupSourceSelector(){
    const customBtn=$('#dietModeCustom'),deskBtn=$('#dietModeDesk');
    const customPanel=$('#dietCustomModePanel'),deskPanel=$('#dietDeskModePanel');
    if(!customBtn||!deskBtn||!customPanel||!deskPanel)return;

    const setMode=function(mode){
      dietFollowupChartMode=mode==='desk'?'desk':'custom';
      const isDesk=dietFollowupChartMode==='desk';
      customBtn.classList.toggle('active',!isDesk);
      deskBtn.classList.toggle('active',isDesk);
      customPanel.hidden=isDesk;
      deskPanel.hidden=!isDesk;
      if(isDesk)loadFollowupDietDocuments();
    };

    customBtn.onclick=function(){setMode('custom');};
    deskBtn.onclick=function(){setMode('desk');};

    const openDesk=$('#openDietChartDesk');
    if(openDesk)openDesk.onclick=function(){
      if(!followClient)return toast('Select a client first');
      const clientName=followClient.patient_name||followClient.first_name||followClient.name;
      NON_DASH_FILTER_STATE=Object.assign({},NON_DASH_FILTER_STATE||{}, {
        search:clientName,
        client:followClient.name
      });
      switchView('dietcharts');
      const search=$('#lifeSearch'),selected=$('#lifeSelectedClient');
      if(search)search.value=clientName;
      if(selected)selected.value=followClient.name;
      applyFilters();
      setTimeout(function(){const view=$('#view-dietcharts');if(view)view.scrollIntoView({behavior:'smooth',block:'start'});},0);
    };

    setMode('custom');
  }
  async function saveDietBuilderAndSendWhatsapp(){
    if(!followClient)return toast('Select a client first');
    if(!dietBuilderReadRows().length)return toast('Add at least one food row');
    const btn=$('#dietSaveWhatsapp'),status=$('#dietSaveStatus');
    if(btn){btn.disabled=true;btn.textContent='Saving…';}
    if(status)status.textContent='Saving Diet Followup and diet rows…';
    if($('#followupRemarks')&&!$('#followupRemarks').value.trim())$('#followupRemarks').value='Diet chart prepared and sent on WhatsApp.';
    try{
      const doc=await saveRealFollowup(false,{keepView:true,suppressSuccessToast:true,extraResponse:'Diet chart: '+dietBuilderReadRows().length+' food rows · '+dietRound(dietBuilderTotals().kcal,0)+' kcal · '+dietRound(dietBuilderTotals().protein,1)+' g protein'});
      if(!doc)throw new Error('Client Followup could not be saved');
      DATA.feedbacks.unshift(doc);FOLLOWUP_DISPLAY_ID_CACHE_KEY='';
      const digits=String(followClient.mobile||followClient.phone||'').replace(/\D/g,''),phone=digits.length===10?'91'+digits:digits;
      if(phone)window.open('https://wa.me/'+phone+'?text='+encodeURIComponent(dietBuilderWhatsappText()),'_blank','noopener');
      if(status)status.textContent='Saved '+doc.name+(phone?' · WhatsApp opened':' · No mobile number available');
      toast('Diet followup '+doc.name+' saved');
      applyFilters();
    }catch(e){('Diet chart save failed', e, void 0);if(status)status.textContent='Could not save: '+(e.message||e);toast('Diet chart could not save: '+(e.message||e));}
    finally{if(btn){btn.disabled=false;btn.textContent='Save and send on WhatsApp';}}
  }
