  function syncDetailedFollowupDateInputs(){
    $$('.life-detail-date-native').forEach(function(input){
      const wrap=input.closest('.life-detail-date-wrap');
      const display=wrap&&wrap.querySelector('.life-detail-date-display');
      if(!display)return;
      const sync=function(){display.value=input.value?fmtDate(input.value):'';};
      if(input.dataset.lifeDetailDateBound!=='1'){
        input.dataset.lifeDetailDateBound='1';
        input.addEventListener('input',sync);
        input.addEventListener('change',sync);
        try{
          const descriptor=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value');
          if(descriptor&&descriptor.get&&descriptor.set){
            Object.defineProperty(input,'value',{
              configurable:true,
              enumerable:true,
              get(){return descriptor.get.call(this);},
              set(v){descriptor.set.call(this,v);sync();}
            });
          }
        }catch(e){('Could not bind detailed date formatter', input.id, e, void 0);}
      }
      sync();
    });
  }

  function bindCommonFollowupDateAndTime(){
    const dateInput=$('#followupDate');
    const nextInput=$('#followupNext');
    const timeInput=$('#followupTime');
    const now=new Date();
    const todayIso=iso(now);
    const yesterdayDate=new Date(now.getFullYear(),now.getMonth(),now.getDate()-1);
    const yesterdayIso=iso(yesterdayDate);

    function bindFormattedDate(input,opts){
      if(!input)return;
      opts=opts||{};
      if(opts.min)input.min=opts.min;
      else input.removeAttribute('min');
      if(opts.max)input.max=opts.max;
      else input.removeAttribute('max');

      let wrap=input.closest('.life-common-date-wrap');
      let display=wrap&&wrap.querySelector('.life-common-date-display');
      if(!wrap){
        wrap=document.createElement('span');
        wrap.className='life-common-date-wrap';
        input.parentNode.insertBefore(wrap,input);
        wrap.appendChild(input);
        display=document.createElement('input');
        display.type='text';
        display.readOnly=true;
        display.tabIndex=-1;
        display.className='life-common-date-display';
        display.placeholder='DD-MMM-YYYY';
        wrap.insertBefore(display,input);
        const icon=document.createElement('span');
        icon.className='life-common-date-icon';
        icon.textContent='▣';
        wrap.appendChild(icon);
      }

      const sync=function(){
        if(opts.min&&input.value&&input.value<opts.min){
          input.value=opts.min;
          toast('Followup Date can only be today or yesterday');
        }
        if(opts.max&&input.value&&input.value>opts.max){
          input.value=opts.max;
          toast('Future Followup Date is not allowed');
        }
        display.value=input.value?fmtDate(input.value):'';
      };

      if(input.dataset.lifeCommonDateBound!=='1'){
        input.dataset.lifeCommonDateBound='1';
        input.addEventListener('input',sync);
        input.addEventListener('change',sync);
      }
      sync();
    }

    if(dateInput&&!dateInput.value)dateInput.value=todayIso;
    bindFormattedDate(dateInput,{min:yesterdayIso,max:todayIso});
    bindFormattedDate(nextInput,{});

    if(timeInput){
      // Every new followup starts with the actual current local time.
      // HTML <input type="time"> expects HH:MM (24-hour) internally;
      // the browser can display it as 05:33 PM according to the user's locale.
      const currentTime=String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0');
      timeInput.value=currentTime;
      timeInput.defaultValue=currentTime;
      timeInput.dataset.lifeDefaultCurrentTime='1';
    }

    if(!document.getElementById('life-common-followup-date-style')){
      const st=document.createElement('style');
      st.id='life-common-followup-date-style';
      st.textContent='.life-common-date-wrap{position:relative;display:block;width:100%}.life-common-date-wrap .life-common-date-display{position:relative;z-index:1;width:100%!important;height:100%!important;min-height:39px!important;margin:0!important;padding:7px 38px 7px 10px!important;border:1px solid #cfd8cf!important;border-radius:5px!important;background:#fff!important;color:#111!important;-webkit-text-fill-color:#111!important;font:500 12px "Segoe UI",Arial,sans-serif!important;pointer-events:none!important}.life-common-date-wrap>input[type="date"]{position:absolute!important;inset:0!important;z-index:3!important;width:100%!important;height:100%!important;min-height:39px!important;margin:0!important;opacity:0!important;cursor:pointer!important}.life-common-date-icon{position:absolute;right:12px;top:50%;transform:translateY(-50%);z-index:2;pointer-events:none;color:#172019;font-size:14px}';
      document.head.appendChild(st);
    }
  }
