  function initPendingDueAmountLimit(){
    const input=$('#dueAmount');
    if(!input)return;
    const maxAmount=Math.max(0,num(input.max));
    const clamp=function(showMessage){
      let raw=String(input.value==null?'':input.value).trim();
      if(raw==='')return;
      let value=Number(raw);
      if(!Number.isFinite(value)){input.value='0';return;}
      if(value<0){input.value='0';if(showMessage)toast('Amount promised cannot be below ₹0');return;}
      if(value>maxAmount){
        input.value=String(maxAmount);
        if(showMessage)toast('Amount promised cannot exceed pending balance '+money(maxAmount));
      }
    };
    input.addEventListener('input',function(){clamp(false);});
    input.addEventListener('change',function(){clamp(true);});
    input.addEventListener('blur',function(){clamp(true);});
  }
