  /* =========================================================
     COLLAPSED SIDEBAR — ICON HOVER TOOLTIP
     Shows the real menu name beside the hovered icon.
     The tooltip is fixed to <body>, so it cannot be clipped by
     the sidebar/nav scroll container.
     ========================================================= */
  function setupSidebarTooltips(){
    const side=$("#lifeSide");
    const nav=$("#lifeNav");
    if(!side||!nav)return;

    let tip=document.getElementById("lifeSidebarTooltip");
    if(!tip){
      tip=document.createElement("div");
      tip.id="lifeSidebarTooltip";
      tip.className="life-sidebar-tooltip";
      tip.setAttribute("role","tooltip");
      tip.hidden=true;
      document.body.appendChild(tip);
    }

    const hideTip=()=>{
      tip.hidden=true;
      tip.classList.remove("show");
      tip.removeAttribute("data-for-view");
    };

    const showTip=btn=>{
      if(!side.classList.contains("collapsed")){
        hideTip();
        return;
      }
      const labelEl=btn.querySelector("b");
      const label=(labelEl&&labelEl.textContent||btn.getAttribute("aria-label")||"").trim();
      if(!label)return;

      btn.dataset.menuLabel=label;
      btn.title=label; // browser fallback
      tip.textContent=label;
      tip.dataset.forView=btn.dataset.view||"";
      tip.hidden=false;

      // Measure after making it visible.
      const r=btn.getBoundingClientRect();
      const tr=tip.getBoundingClientRect();
      const gap=10;
      const left=Math.min(window.innerWidth-tr.width-8,r.right+gap);
      const top=Math.max(8,Math.min(window.innerHeight-tr.height-8,r.top+(r.height-tr.height)/2));
      tip.style.left=Math.round(left)+"px";
      tip.style.top=Math.round(top)+"px";
      requestAnimationFrame(()=>tip.classList.add("show"));
    };

    nav.querySelectorAll("button[data-view]").forEach(btn=>{
      const label=btn.querySelector("b");
      if(label){
        const text=label.textContent.trim();
        btn.dataset.menuLabel=text;
        btn.title=text;
      }
      btn.addEventListener("mouseenter",()=>showTip(btn));
      btn.addEventListener("focus",()=>showTip(btn));
      btn.addEventListener("mouseleave",hideTip);
      btn.addEventListener("blur",hideTip);
      btn.addEventListener("click",hideTip);
    });

    window.addEventListener("resize",hideTip);
    window.addEventListener("scroll",hideTip,true);

    // Expose a small helper so the collapse button can hide an open tooltip.
    side._lifeHideTooltip=hideTip;
  }

